) as v(code, form, scores, total, grade)
where exists (select 1 from "PFormPro_employees" e where e.emp_code = v.code)
on conflict (cycle_id, emp_code) do update set form = excluded.form, status = 'done', scores = excluded.scores, total = excluded.total, grade = excluded.grade, updated_at = excluded.updated_at;

commit;

-- ตรวจผล
select grade, count(*) from "PFormPro_evaluations" where cycle_id = (select id from "PFormPro_eval_cycles" where year_be = 2569 and round = 1) group by grade order by grade;
